//! The words district-ffi itself writes, in the language the core writes in.
//!
//! [`s`] holds one function per entry of `l10n/ffi.toml`, generated by
//! `scripts/gen-l10n.py` (`tools/l10n/l10n.py`, rust backend); each takes the
//! locale first. [`l`] is the core's locale (`CoreConfig::locale`, from the
//! user's languages): every screen calls `s::<key>(l())`, so district-ffi
//! and the core always speak the same language. Until the French is written
//! the French arm of every function carries the English.

pub use district_l10n::Locale;

/// The core's own sentences and labels (`district_l10n::strings`), for the
/// screens district-ffi lays out with the core's words: what the core's public
/// constants (`CallLog::FAILED_TITLE`) say in English, in the core's language.
pub use district_l10n::strings as cs;

/// district-ffi's sentences and labels, from `l10n/ffi.toml`.
#[rustfmt::skip]
#[path = "generated/strings.rs"]
pub mod s;

/// The language the core writes in now, which district-ffi's own words follow.
#[must_use]
pub fn l() -> Locale {
    district_l10n::current()
}

/// Every function of [`s`], called in both languages and held to its catalog.
#[cfg(test)]
#[rustfmt::skip]
#[path = "generated/accessors.rs"]
mod accessors;
